/*Enable touse bootstrap icons*/
import 'bootstrap-icons/font/bootstrap-icons.css';

/*Enable bootstrap*/
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap/dist/js/bootstrap.min.js';

/*Connect stylesheet for App.jsx*/
import './App.css';

/*Connecting components*/
import Header from './components/Header';
import SideBar from './components/SideBar';
import Main from './components/Main';
import SignIn from './components/SignIn';

import { useState, useEffect } from 'react';

import { useNavigate, Routes, Route} from "react-router-dom";

import { Modal, Button } from 'react-bootstrap';



/*Data implementation*/
import { getSuppliers, getProducts, updateProduct, addProduct, getWarehouseInfo} from './data/dataFetching';
import { getEmployees, updateEmployee, updateAddress, deleteEmployee, getEmployeeById, addAddress, addEmployee } from './data/ServerData';

function App() {

  const navigate = useNavigate();

  // State for suppliers
  const [suppliers, setSuppliers] =useState([]);
  // State for products
  const [product, setProducts] = useState([]);

  const [authorisedUser, setauthorisedUser] = useState({});

  const [showErrorModal, setShowErrorModal] = useState(false);

  useEffect(() => {
    const storedUser = localStorage.getItem('authorisedUser');
    if (storedUser) {
      setauthorisedUser(JSON.parse(storedUser));
    }
  }, []);

  function login(email, password) {

    getEmployees().then((employees) => {

      let authok = false;
      for (let employee of employees) {
        if (email == employee.email && password == employee.password) {
          setauthorisedUser(employee);
          authok = true;
          localStorage.setItem('authorisedUser', JSON.stringify(employee));
          navigate("/inventory" );
        }
      }

      if (!authok) {
        setShowErrorModal(true);
      }
    });
  }

  const handleCloseErrorModal = () => setShowErrorModal(false);

  function logout() {
    setauthorisedUser({});

    navigate("/signin" );
  }


  // Add supplier
  const addSupplier = (newSupplier) => {
    getSuppliers([getSuppliers, newSupplier]);
  };

  // Delete supplier
  const deleteSupplier = (supplierId) => {
    setSuppliers((prevSuppliers) => {
      const updatedSuppliers = prevSuppliers.filter(supplier => supplier.id !== supplierId);
      return [...updatedSuppliers]; // Update an new array
    });
  };

  // update supplier
  const updateSupplier = (updatedSupplier) => {
    setSuppliers((prevSuppliers) => 
      prevSuppliers.map(supplier =>
        supplier.id === updatedSupplier.id ? updatedSupplier : supplier
      )
    );
  };

  
  // Add Product
  const addProduct = (newProduct) => {
    setProducts((prevProducts) => [...prevProducts, newProduct]); // Lägg till den nya produkten i listan
  };

  // Delete Product
  const deleteProduct = (productId) => {
    setProducts((prevProducts) => {
      const updatedProduct = prevProducts.filter(product => product.id !== productId);
      return [...updatedProduct]; // Update an new array
    });
  };

  // Update product
  const updateProduct = (updatedProduct) => {
    setProducts((prevProducts) =>
      prevProducts.map(product =>
        product.id === updatedProduct.id ? updatedProduct : product
      )
    );
  };
  
  

  


  return <>
    <Header authorisedUser={authorisedUser} logout={logout} />
    <Routes>
      <Route path='/signin' element={<SignIn login={login} />} />
      <Route path="/*" element={
        <>
          <SideBar authorisedUser={authorisedUser}/>
          <Main
            authorisedUser={authorisedUser}
            getSuppliers={getSuppliers} 
            suppliers={suppliers} 
            addSupplier={addSupplier} 
            deleteSupplier={deleteSupplier} 
            updateSupplier={updateSupplier}  
            getProducts={getProducts} 
            updateProduct={updateProduct} 
            addProduct={addProduct} 
            deleteProduct={deleteProduct}
            getWarehouseInfo={getWarehouseInfo}
            
            getEmployees = {getEmployees}
            updateEmployee = {updateEmployee} 
            updateAddress = {updateAddress} 
            deleteEmployee = {deleteEmployee}
            getEmployeeById = {getEmployeeById}
            addAddress = {addAddress} 
            addEmployee = {addEmployee} />
        </>
      } />
      
    </Routes>

    <Modal show={showErrorModal} onHide={handleCloseErrorModal} className="modal-centered">
      <Modal.Header closeButton>
        <Modal.Title>Authentication Error</Modal.Title>
      </Modal.Header>
      <Modal.Body>
        Wrong email or password! If you forget your password, contact us with email: inventhor@support.no
      </Modal.Body>
      <Modal.Footer>
        <Button variant="secondary" onClick={handleCloseErrorModal}>
          Close
        </Button>
      </Modal.Footer>
    </Modal>

    {/*<SideBar />
    <Main getSuppliers={getSuppliers} addSupplier={addSupplier} getEmployees={getEmployees} addEmployees={addEmployees} />*/}

  </>;
}

export default App;
